from kd_common import *
i=8
Z=lambda q,a:[('z',q),('b',a)]
def shrine(c='#7a3b1f'): return '<rect x="-40" y="-50" width="80" height="50" fill="#e9d6c0"/><path d="M-52 -50 L0 -84 L52 -50z" fill="'+c+'"/><rect x="-10" y="-30" width="20" height="30" fill="#5a3a1a"/>'
def horse(): return '<path d="M-30 0 v-30 h50 l12 -18 l8 4 l-8 22 v22 M-24 -30 v30 M14 -30 v30" stroke="#7a3b1f" stroke-width="6" fill="none"/><path d="M-30 -30 h50" stroke="#e0a800" stroke-width="4"/>'
def ox(): return '<ellipse rx="34" ry="16" cy="-24" fill="#8a7a6a"/><path d="M-24 -12 v12 M24 -12 v12 M-12 -12 v12 M12 -12 v12" stroke="#6a5a4a" stroke-width="5"/><circle cx="36" cy="-32" r="10" fill="#8a7a6a"/><path d="M40 -42 l8 -8" stroke="#c9b28a" stroke-width="3"/><rect x="-24" y="-48" width="40" height="12" fill="#f4f1ea"/>'
fw=foreword(i,['Beyond Kāverī and Igguthappa, every Kodava village has its own gods. The most common is the goddess <b>Bhagavatī</b>, also called <b>Bhadrakāḷī</b> or <b>Povvadi</b>, worshipped in nearly every village; with her are Aiyappa of the forest, Mahādēva, and many guardian spirits. Their annual festivals, called <b>namme</b>, fill the mands with drums, horn dances, masked players and wooden horses.',
 'This part covers the village goddess and her companions, the sacred groves, the rules before a namme, the festival rituals, the Kerala-linked kōla performers, the disguise festival and the old rice-gifts to a temple across the border.',
 'The mand where these festivals happen is in '+L('/kodagu/mand-and-dances/','Part 6')+'; Igguthappa in '+L('/kodagu/igguthappa/','Part 5')+'. Next: '+L('/kodagu/temples/','temples')+'.'],Z('Many gods for one village?','A goddess, a forest god and their guardians. Each looks after something.'))
gl=glance([('Village goddess','Bhagavatī, Bhadrakāḷī or Povvadi'),('Also','Aiyappa (forest god), Mahādēva, Cāmuṇḍi, guardian spirits'),('Festival','Namme: the annual village festival'),('Timing','Varies; many in spring (Kodava Mīnyār, about April–May)'),('Before','Namme kaṭṭ: rules kept by the village'),('Rituals','Processions, drums, kombāṭ, wooden horses'),('Performers','Communities such as Banna, Maleya and others'),('Groves','Dēvarakāḍu: sacred forests'),('Kerala link','Gods and rites from across the Ghats'),('Shared','Kodavas and other communities together')],
 S('A village shrine on a mand with a sacred grove and drummers',g(280,210,1.5,shrine())+g(100,215,1.8,tree('#2f6a3a'))+g(470,215,1.8,tree('#3a8a4a'))+g(180,215,1,dudi())+g(390,215,1,kodava_man()),'#d8e8c8',215),Z('Are these Hindu gods?','Yes, in local forms, many tied to Kerala traditions.'),'Every village <b>has its goddess</b>.')
bhag=reading('bhagavati','BHAGAVATĪ','The goddess of every village',S('A fierce, many-armed goddess in a small shrine',g(280,210,1.8,devi(sari='#c0392b',items=('sword','trident')))+g(120,215,1,lamp())+g(440,215,1,lamp()),'#fff3cf',215),
 ['<b>Names.</b> Bhadrakāḷī, also called Bhagavatī or <b>Povvadi</b>, is worshipped in every village in Kodagu.','<b>Protector.</b> She guards the village from disease, danger and misfortune.','<b>Arrival.</b> Temple traditions tell how she came to Kodagu: one says she came from Sōḷi village with Viṣṇumūrti and an assistant god, and with the communities who serve her rites. (Temple tradition.)','<b>Many temples.</b> Each village or pair of villages has its own Bhadrakāḷī temple.','<b>Festival.</b> Her annual festival is the <b>Povvadi namme</b> or Bhagavatī namme.'],Z('Fierce?','Fierce to danger, kind to her people.'),'The guardian <b>of each village</b>.')
others=cards('others','HER COMPANIONS','Forest gods and guardians',fig_row('A forest god with bow, Śiva liṅga, a guardian with sword, a snake stone',[(god('#2a9d6f'),1.1),(LINGA,1) if False else ('<ellipse rx="16" ry="6" fill="#7a6a5a"/><rect x="-8" y="-28" width="16" height="28" rx="8" fill="#5a5a5a"/>',1.2),(kola_dancer(),1),('<rect x="-12" y="-36" width="24" height="36" rx="10" fill="#8a8a7a"/><path d="M-4 -30 q8 8 0 16 q-8 8 0 14" stroke="#2f8a3a" stroke-width="3" fill="none"/>',1.2)],['Aiyappa','Mahādēva','guardian','nāga'],gy=150),
 [('🏹','Aiyappa','A forest god of the hills, worshipped in groves; distinct in form from Sabarimala.'),('🔱','Mahādēva','Śiva, widely worshipped in nāḍ temples.'),('⚔️','Guardians','Spirits who guard boundaries and serve the goddess.'),('🐍','Nāgas','Snake shrines and stones.'),('🌳','Grove gods','Deities of the dēvarakāḍu.'),('🧘','Viṣṇumūrti','Named in some Bhagavatī temple traditions.')],None,'A goddess <b>with a household of gods</b>.',intro='The set of gods differs from village to village; these are the common ones named in accounts.')
grove=reading('groves','DĒVARAKĀḌU','The sacred groves',S('A thick patch of forest among coffee estates with a small shrine inside',g(280,210,2.4,tree('#2f6a3a'))+g(200,215,2,tree('#3a8a4a'))+g(360,215,2,tree('#2f6a3a'))+g(280,215,.7,shrine())+g(80,215,1,coffee())+g(500,215,1,coffee()),'#d8e8c8',230),
 ['<b>Dēvarakāḍu.</b> “God’s forests”: sacred groves attached to village deities.','<b>Protected.</b> By tradition no tree may be felled and no animal hunted inside.','<b>Many.</b> Kodagu has a very large number of these groves, from small patches to large woods.','<b>Ecology.</b> They shelter old trees, springs and wildlife among the coffee.','<b>Threats.</b> Encroachment and neglect threaten some; communities and the state work to protect them.'],Z('Why not cut them?','The god lives there. Faith protected the forest before any law did.'),'Forests <b>kept by faith</b>.')
katt=reading('katt','BEFORE THE NAMME','Namme kaṭṭ: the rules',S('Villagers gather at the temple to announce the festival; a flag is raised',g(280,210,1.4,shrine())+g(420,210,1,flagpole())+''.join(g(100+k*50,215,.9,kodava_man()) for k in range(3)),'#fff3cf',215),
 ['<b>Announcement.</b> About a week before, villagers gather at the temple to announce the <b>namme kaṭṭ</b>.','<b>Rules.</b> For those days the village keeps rules: often no meat, no hunting, no noise, no leaving the village, by local custom.','<b>Preparation.</b> Costumes, horses and offerings are made ready.','<b>Blessing.</b> In one tradition villagers first visit a nearby Bhagavatī temple with duḍi and drums to seek blessings for a smooth festival.','<b>Turns.</b> Sister villages may host in alternate years.'],Z('What happens if you break the rules?','Elders decide. Most people would not dare.'),'A village <b>holds its breath</b>.')
namme=reading('namme','THE FESTIVAL','A namme day',S('A procession with two wooden horses carried to the temple, drummers ahead',g(160,215,1.4,horse())+g(300,215,1.4,horse())+g(450,210,1.2,shrine())+g(70,215,1,dudi()),'#d8e8c8',215),
 ['<b>Processions.</b> Village gods’ emblems are carried to the Bhadrakāḷī temple.','<b>Horses.</b> In some villages wooden horses (kudure) of the gods are dressed and carried in procession.','<b>Kombāṭ.</b> The horn dance is performed at Bhadrakāḷī festivals.','<b>Offerings.</b> Rice, coconuts, fowl and other offerings by local custom.','<b>Feast.</b> The village eats together on the mand.'],Z('Horses?','Wooden ones, carried on men’s shoulders. The gods ride.'),'The gods <b>ride wooden horses</b>.')
kola=reading('kola','THE KŌLAS','Gods who dance',S('A masked dancer in a red skirt and tall headdress dancing at night before a shrine',g(280,215,2.2,kola_dancer('#c0392b'))+g(120,215,1,shrine())+g(440,200,.8,flame()),'#20243a',230),
 ['<b>Kōla.</b> In several villages the gods appear as <b>kōlas</b>: performers in costume and paint who embody the deity, as in Kerala’s theyyam and Tulu Nadu’s bhūta kōla.','<b>Performers.</b> These rites are traditionally performed by particular communities, such as the Banna and Maleya.','<b>Kerala roots.</b> Temple traditions tie the gods and their performers to Kerala.','<b>Possession.</b> The kōla speaks and blesses as the god.','<b>Compare.</b> See '+L('/tulunadu/daiva/bhuta-kola/','Bhūta Kōla in Tulu Nadu')+'.'],Z('Like Tulu Nadu?','Cousins across the hills. Kodagu sits between Kerala and the Tulu coast.'),'The god <b>puts on a face</b>.')
disg=reading('bod','THE DISGUISE FESTIVAL','Bōḍ namme',S('Villagers in disguises and painted faces laughing in a group',''.join(g(100+k*80,215,1,person(['#c0392b','#1d4f8a','#2a9d6f','#e0a800','#6a3d9a','#8a5a2a'][k]))+f'<circle cx="{100+k*80}" cy="148" r="9" fill="{["#f4f1ea","#2a2a2a","#e0a800","#c0392b","#f4f1ea","#2a9d6f"][k]}"/>' for k in range(6)),'#fff3cf',215),
 ['<b>Bōḍ.</b> Some villages hold a festival, often called <b>Bōḍ namme</b>, in which people go about in disguise.','<b>Groups.</b> Kodavas, Kembaṭṭis and others perform in groups, in costume, as characters.','<b>Licence.</b> For those days teasing and comedy are allowed.','<b>Old.</b> Such festivals appear in the 1870 Gazetteer of Coorg.','<b>Where.</b> Accounts name villages such as Halligaṭṭ, Chembebelloor and Bilugunda.'],Z('Why disguises?','Some say to please the goddess with laughter. All say it is great fun.'),'Faith <b>with a sense of humour</b>.')
rice=reading('baithur','ACROSS THE BORDER','Rice for Baithurappa',S('Oxen carrying sacks of rice along a hill path to a temple in Kerala',hills(560,120,'#5a9a5a')+g(150,215,1.2,ox())+g(290,215,1.2,ox())+g(470,210,1.2,shrine()),'#d8e8c8',215),
 ['<b>Baithurappa.</b> The god of Baithūr (Vayathūr) near Iritty, in Kerala’s Kannur district, is honoured by Kodagu people.','<b>Eth-pōrāṭa.</b> Before his festival, loads of rice were sent from Kodagu on oxen.','<b>Prasāda.</b> The rice is cooked and served to devotees during the festival.','<b>Visitors.</b> Kodagu people still visit the annual festival.','<b>Meaning.</b> It shows the old bond across the Ghats.'],Z('Kodava gods in Kerala?','The hills never were a wall. Gods, rice and families crossed them.'),'Rice <b>across the Ghats</b>.')
endp=end(i,['<b>Goddess.</b> Bhagavatī, Bhadrakāḷī or Povvadi in every village.','<b>Companions.</b> Aiyappa, Mahādēva, guardians, nāgas.','<b>Groves.</b> Dēvarakāḍu, protected by faith.','<b>Namme.</b> Rules, processions, horses, kombāṭ, kōlas and disguises.','<b>Kerala.</b> Baithurappa and the rice gifts.'],'Part 10 is the temples of Kodagu.','Every village has its goddess')
src=sources([('Village festivals:','Deccan Herald (Hitha Nanjappa), “Of a namme in native villages” (Bhadrakāḷī/Bhagavatī/Povvadi; kombāṭ; alternate hosting); Deccan Herald, “A unique temple festival” (Arapattu Bhagavatī tradition: Sōḷi, Viṣṇumūrti, Banna, Maleya and Pale); Kodava heritage site (Hebbettageri and Halligaṭṭ festivals: Mīnyār, namme kaṭṭ, kudure); Deccan Herald on Kembaṭṭi traditions (Pannaṅgālatamme, disguise performances, 1870 Gazetteer); Deccan Herald, “Of rice, oxen and pilgrimages” (Baithurappa, eth-pōrāṭa).'),('Groves:','Wikipedia “Kodava people” (dēvarakāḍu).')],'the specific namme rules vary by village and are generalised; the name “Bōḍ namme” is used as reported for some villages.','Deity names vary locally.')
finish(i,'PART 9 OF 12 · BHAGAVATĪ · GROVES · NAMME',covart('A masked kōla dancer before a village shrine in a sacred grove',g(220,190,1.6,kola_dancer('#c0392b'))+g(90,190,1.2,tree('#2f6a3a'))+g(350,190,1,shrine())),'Every village has its goddess',
 'The <b>village deities</b> of Kodagu: Bhagavatī and Bhadrakāḷī, Aiyappa and the guardians, the sacred groves, and the <b>namme</b> festivals with their horses, horn dances, kōlas and disguises.',
 'Village deities of Kodagu explained and illustrated: Bhagavatī, Bhadrakāḷī (Povvadi), Aiyappa and guardian spirits, dēvarakāḍu sacred groves, namme kaṭṭ rules, festival processions with wooden horses, kōlas, disguise festivals and Baithurappa.',
 [fw,gl,bhag,others,grove,katt,namme,kola,disg,rice,endp,src])
